/* Browser-only profile and conversations. No messages are transmitted. */
let profile = {name:'',campus:'',bio:''};
try { const value=JSON.parse(localStorage.getItem('dormmart-profile-v1'));for(const key of Object.keys(profile))if(typeof value?.[key]==='string')profile[key]=value[key]; } catch {}
let conversations=readStore('dormmart-messages-v1',[]).filter(c=>c&&Number.isSafeInteger(c.itemId)&&typeof c.title==='string'&&typeof c.owner==='string'&&Array.isArray(c.messages)).map(c=>({...c,messages:c.messages.filter(m=>m&&['you','demo'].includes(m.from)&&typeof m.text==='string'&&typeof m.time==='string')}));
let profileFilter='all';
function saveCommunity(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Could not save. Browser storage is full or unavailable. Please try again.');return false}}
function profileListing(x){return `<article class="owned-card">${itemPhoto(x)}<div class="owned-content"><p class="eyebrow">${x.mode==='rent'?'FOR RENT':x.mode==='buy'?'FOR SALE':'FREE SHARING'}</p><h3>${escapeHTML(x.title)}</h3><p>${money(x.price)}${x.mode==='rent'?' / day':''} · ${escapeHTML(x.condition)}</p><p class="micro">${escapeHTML(x.area||'Pickup area not set')}</p>${x.pickupAddress?`<details class="pickup-details"><summary>My pickup address</summary><p>${escapeHTML(x.pickupAddress.address)}, ${escapeHTML(x.pickupAddress.city)} ${escapeHTML(x.pickupAddress.postcode)}</p><small>Only shown to you on this browser.</small></details>`:''}${availabilityDatesHTML(x)}<label>Status<select data-listing-status="${x.id}" aria-label="Availability for ${escapeHTML(x.title)}">${['available',x.mode==='buy'?'sold':'rented'].map(status=>`<option value="${status}" ${(x.status||'available')===status?'selected':''}>${status==='available'?'Available':status==='sold'?'Sold':x.mode==='share'?'On loan':'Rented out'}</option>`).join('')}</select></label><div class="owned-actions"><button class="button small" data-edit-listing="${x.id}">Edit item</button><a class="text-btn" href="#item-${x.id}">View</a><button class="delete-button" data-remove-listing="${x.id}">Delete item</button></div></div></article>`}
function refreshProfile(){
 if(location.hash!=='#profile')return;
 const listings=userListings.filter(x=>profileFilter==='all'||x.mode===profileFilter);
 $('#profile-view').innerHTML=`<div class="profile-heading"><div><p class="eyebrow">YOUR CAMPUS CORNER</p><h1>My profile<span class="logo-dot"> ✳</span></h1><p>Your details, your listings, all in one place.</p></div><button class="button" id="profile-add">+ List an item</button></div><div class="profile-layout"><aside class="profile-panel"><div class="profile-avatar" aria-hidden="true">${escapeHTML((profile.name||'Y').slice(0,1).toUpperCase())}</div><h2>${escapeHTML(profile.name||'Your demo profile')}</h2><p>${escapeHTML(profile.campus||'Add your campus below')}</p><span class="badge-chip">Demo account · unverified</span><form id="profile-form" class="detail-form"><label>Display name<input type="text" name="name" maxlength="60" value="${escapeHTML(profile.name)}" placeholder="What should neighbours call you?"></label><label>Campus / locality<input type="text" name="campus" maxlength="100" value="${escapeHTML(profile.campus)}" placeholder="Your campus or neighbourhood"></label><label>About you<textarea name="bio" maxlength="300" rows="3" placeholder="A little about yourself">${escapeHTML(profile.bio)}</textarea></label><button class="button" type="submit">Save profile</button><p class="micro">Saved only on this browser. Sign-in details are never stored.</p></form><div class="profile-links"><a class="text-btn" href="#wanted">Item request board ↗</a><button class="text-btn" id="profile-requests">My booking requests (${requests.length})</button><a class="text-btn" href="#messages">My messages (${conversations.length})</a><button class="text-btn" id="profile-signout">Sign out</button></div></aside><div class="profile-listings"><div class="profile-stats">${[['rent','For rent'],['buy','For sale'],['share','Sharing']].map(([mode,label])=>`<div><strong>${userListings.filter(x=>x.mode===mode).length}</strong><span>${label}</span></div>`).join('')}</div><div class="section-heading"><h2>My listings <small>(${userListings.length})</small></h2></div><div class="category-row" aria-label="Filter your listings">${[['all','All items'],['rent','For rent'],['buy','For sale'],['share','Sharing']].map(([mode,label])=>`<button class="chip ${profileFilter===mode?'active':''}" data-profile-filter="${mode}" aria-pressed="${profileFilter===mode}">${label}</button>`).join('')}</div><div class="owned-grid">${listings.length?listings.map(profileListing).join(''):`<div class="community-empty"><span aria-hidden="true">↗</span><h3>${userListings.length?'No items in this category yet.':'Your next chapter starts here.'}</h3><p>Items you add on this browser will appear here, ready to edit or delete.</p><button class="button" id="empty-profile-add">List your first item</button></div>`}</div></div></div>`;
 $('#profile-add').onclick=openListingForm;$('#empty-profile-add')?.addEventListener('click',openListingForm);
 $('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),next=Object.fromEntries(['name','campus','bio'].map(k=>[k,String(f.get(k)||'').trim()]));if(saveCommunity('dormmart-profile-v1',next)){profile=next;refreshProfile();toast('Profile saved on this browser.')}};
 $('#profile-requests').onclick=()=>$('#requests-button').click();
 $('#profile-signout').onclick=()=>{demoSignedIn=false;try{sessionStorage.removeItem('dormmart-demo-session')}catch{}syncAuth();$('#demo-contact').focus()};
 $('#profile-view').querySelectorAll('[data-profile-filter]').forEach(b=>b.onclick=()=>{profileFilter=b.dataset.profileFilter;refreshProfile()});
}
function renderCommunityRoute(hash){
 if(hash.startsWith('#item-'))return false;
 if(hash==='#profile')$('#account-button').setAttribute('aria-current','page');else $('#account-button').removeAttribute('aria-current');
 const isProfile=hash==='#profile',isMessages=hash==='#messages'||hash.startsWith('#messages-');
 $('#profile-view').hidden=!isProfile;$('#messages-view').hidden=!isMessages;
 if(!isProfile&&!isMessages)return false;
 lastPage=hash.slice(1);
 if($('#modal').open)closeModal();$('#home-view').hidden=true;$('#explore-view').hidden=true;
 document.querySelectorAll('.header nav a').forEach(a=>{a.removeAttribute('aria-current');if(isMessages&&a.hash==='#messages')a.setAttribute('aria-current','page')});
 document.title=(isProfile?'My profile':'Messages')+' — DormMart';
 if(isProfile)refreshProfile();else renderMessages(Number(hash.slice(10))||null);
 window.scrollTo(0,0);return true;
}
function startConversation(id){
 const item=LISTINGS.find(x=>x.id===id);if(!item||item.custom)return;
 if(!conversations.some(c=>c.itemId===id)){
  const next=[{itemId:id,title:item.title,owner:item.owner,messages:[]},...conversations];
  if(!saveCommunity('dormmart-messages-v1',next))return;conversations=next;
 }
 location.hash='messages-'+id;
}
function renderMessages(selected){
 const active=conversations.find(c=>c.itemId===selected)||(!selected?conversations[0]:null);
 $('#messages-view').innerHTML=`<div class="profile-heading"><div><p class="eyebrow">A LITTLE CONVERSATION GOES A LONG WAY</p><h1>Messages</h1><p>Ask about condition, availability and pickup.</p></div><a class="arrow-link" href="#explore">Find an item ↗</a></div><p class="notice">Demo inbox · Messages stay on this browser and are not sent to real people. Use “Simulate reply” to try a conversation.</p><div class="inbox-layout"><aside class="conversation-list" aria-label="Conversations">${conversations.length?conversations.map(c=>`<a class="conversation ${active===c?'selected':''}" ${active===c?'aria-current="page"':''} href="#messages-${c.itemId}"><span class="conversation-avatar">${escapeHTML(c.owner.slice(0,1))}</span><span><strong>${escapeHTML(c.owner)}</strong><span>${escapeHTML(c.title)}</span><small>${escapeHTML(c.messages.at(-1)?.text||'Start the conversation')}</small></span></a>`).join(''):'<p>No conversations yet.</p>'}</aside><div class="conversation-panel">${active?`<div class="conversation-header"><h2>${escapeHTML(active.owner)}</h2><a href="#item-${active.itemId}">${escapeHTML(active.title)} ↗</a></div><div class="message-history" role="log" aria-label="Conversation messages">${active.messages.length?active.messages.map(m=>`<div class="message-bubble ${m.from==='you'?'outgoing':'incoming'}"><small>${m.from==='you'?'You':'Simulated owner reply'}</small><p>${escapeHTML(m.text)}</p><time>${escapeHTML(Number.isFinite(Date.parse(m.time))?new Date(m.time).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'')}</time></div>`).join(''):'<p class="micro">Say hello! Ask a question about this item to get started.</p>'}</div><div class="message-tools"><button class="text-btn" id="simulate-reply" ${active.messages.some(m=>m.from==='you')?'':'disabled'}>Simulate reply</button></div><form id="message-form"><label for="message-text">Your message</label><textarea id="message-text" maxlength="1000" rows="2" required placeholder="Hi! Is this still available?"></textarea><div><span class="micro">Demo only · no delivery</span><button class="button" type="submit">Send message ↗</button></div><p id="message-error" role="alert" class="form-error"></p></form>`:'<div class="community-empty"><span aria-hidden="true">✉</span><h2>Good things start with hello.</h2><p>Open an item in Explore and choose Message owner.</p><a class="button" href="#explore">Explore items</a></div>'}</div></div>`;
 if(!active)return;
 function appendMessage(text,from){const next=conversations.map(c=>c===active?{...c,messages:[...c.messages,{text,from,time:new Date().toISOString()}]}:c);if(!saveCommunity('dormmart-messages-v1',next))return false;conversations=next;renderMessages(active.itemId);$('#message-text').focus();return true}
 $('#message-form').onsubmit=e=>{e.preventDefault();const input=$('#message-text'),text=input.value.trim();if(!text){$('#message-error').textContent='Write a message before sending.';return}appendMessage(text,'you')};
 $('#simulate-reply').onclick=()=>appendMessage('Thanks for asking! This is a simulated reply. Please check the listing dates and condition, then agree on a public pickup point.','demo');
 const history=$('.message-history');history.scrollTop=history.scrollHeight;
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-message-item]');if(button)startConversation(Number(button.dataset.messageItem))});
$('#account-button').onclick=()=>{location.hash='profile';route()};
// Keep existing listing deletion and cancellation flows returning to the profile.
showMyListings=function(){if($('#modal').open)closeModal();location.hash='profile';route()};
route();
